import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"17、【隨】 震下兌上","description":"周易尚氏學 - 17、【隨】 震下兌上","frontmatter":{"title":"17、【隨】 震下兌上","description":"周易尚氏學 - 17、【隨】 震下兌上"},"headers":[],"relativePath":"classics/shangshi/022.md","filePath":"classics/shangshi/022.md"}'),s={name:"classics/shangshi/022.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_17、【隨】-震下兌上" tabindex="-1">17、【隨】 震下兌上 <a class="header-anchor" href="#_17、【隨】-震下兌上" aria-label="Permalink to “17、【隨】 震下兌上”">​</a></h1><p>歸藏曰馬徒。馬徒。即周禮太僕職所謂前驅。越語勾踐親為夫差前馬。注前馬前驅。在馬前也。按震為馬。互艮為徒隸。馬徒皆隨貴人馬。前行以闢道。而兌為口。為傳呼。於卦象頗合。茲周易名隨。似取隨時之義。震春。故曰元亨。兌秋。故曰利貞。吉春而夏可賅。言秋而科可賅。元亨利貞。即春夏秋冬。週而復始。循環不窮。故曰隨。隨時而動。不過不忒。故無咎。</p><p>彖曰。隨。剛來而下柔。動而說。隨。大亨貞無咎。而天下隨時。隨時之義大矣哉。</p><p>王肅本。隨時。皆作隨之。將卦義全失。朱於從之過矣。故夫讀易以明理為先也。</p><p>象曰。澤中有雷。隨。君子以晌晦入宴息。艮為君子。又止故宴息。兌為昧為晦。震往。往而遇兌。故曰晌晦。巽伏。故君子法此象。以晌晦人宴息。</p><p>初九。官有渝。貞吉。出門交有功。</p><p>官。蜀才作館。見釋文。惠棟雲。官。古文館。以穆天子傳。官人陳牲為證。按作館是也。艮為館。下卦艮覆。故曰館有渝。渝變也。初至四為正覆良。象覆即於覆取義。易通例也。自覆象失傳。渝之古舊解皆不能說其所以然。而用覆之辭。如蒙掾（無左）如中孚之二三交。詁皆誤矣。渝而得位。故貞吉。與下貞兇為對文。艮為門。初臨之。而震為出。故曰出門。出門則有交接。陽遇陰則通。故有功。凡陽臨重陰者無不吉。此其一也。</p><h3 id="象曰。官有偷。從正吉也。出門交有功。不失也。" tabindex="-1">象曰。官有偷。從正吉也。出門交有功。不失也。 <a class="header-anchor" href="#象曰。官有偷。從正吉也。出門交有功。不失也。" aria-label="Permalink to “象曰。官有偷。從正吉也。出門交有功。不失也。”">​</a></h3><p>失與佚通用。供逸也。震動故不佚。言不敢安逸也。此與比六二不自失。小畜九二亦不自失。皆讀為佚。與吉韻。義詳比九五失前禽注。</p><p>六二。系小子。失丈夫。</p><p>此爻舊解。淆亂至今者。一由卦象失傳。二由同性相敵之理不明也。初震為小子。四艮為丈夫。二近初。故系小子。為六三所隔。不能承四。故失丈夫。易林家人之巽雲。孩子貪餌。以伏震為孩子也。孩子即小子。是焦氏以震為小子。義即本此也。又復之剝雲。夫亡從軍。以剝上艮為夫。是艮為丈夫。焦氏仍本之易。蓋以二人言。初生者長。後生者少。故說卦以震為長子。艮為少子。而以一人言。則初少上老。故經以震為小子。艮為丈夫。先儒不知經取象。往往與說卦不同。不敢直認。豈知象傳所釋至明也。</p><h3 id="象曰。系小子。弗兼與也。" tabindex="-1">象曰。系小子。弗兼與也。 <a class="header-anchor" href="#象曰。系小子。弗兼與也。" aria-label="Permalink to “象曰。系小子。弗兼與也。”">​</a></h3><p>二居初四之間。近初遠四。故曰弗兼與。虞翻謂二應五。以五為小子。五為少女。焉能為小子。失之遠矣。</p><p>六三。系丈夫。失小子。隨有求。句得。句利居貞。</p><p>三近四承陽。故上系文夫。為二所阻。故下失小子。象謂志合下。是明以震為小於。艮為丈夫也。隨有求句。與下隨有獲對文。艮為求。陰承陽故有得。巽為利。鹹六二雲。居吉。茲雲利居貞。似亦以動為戒。蓋上無應。靜而承陽則吉。動則不利。舊解謂之正應上。於居義相背。非也。</p><h3 id="象曰。系丈夫。志合下也。" tabindex="-1">象曰。系丈夫。志合下也。 <a class="header-anchor" href="#象曰。系丈夫。志合下也。" aria-label="Permalink to “象曰。系丈夫。志合下也。”">​</a></h3><p>下謂初。輕以艮為丈夫。以震為小子。可謂明白矣。</p><p>九四。隨有獲。貞兇。有孚。在道以明。何咎。</p><p>下乘重陰得民。故有獲。不當位。前遇敵。故貞兇。然下孚於眾。光明正大。遵循正道。亦無咎也。艮為道。為光明。虞氏命三四全變成離。取明象。迂曲失經旨。大畜彖傳曰。剛健篤實輝光。剛健謂乾。輝光謂艮。是艮為光明。易有明文。</p><h3 id="象曰。隨有獲。其義兇也。有孚在道。明功也。其義兇者。" tabindex="-1">象曰。隨有獲。其義兇也。有孚在道。明功也。其義兇者。 <a class="header-anchor" href="#象曰。隨有獲。其義兇也。有孚在道。明功也。其義兇者。" aria-label="Permalink to “象曰。隨有獲。其義兇也。有孚在道。明功也。其義兇者。”">​</a></h3><p>謂四本不兇。而兇者以不當位也。大畜頤上九皆下孚於陰而吉。</p><p>九五。孚於嘉。吉。</p><p>易林每以震為嘉。蓋本此也。嘉指二。五孚於二。二震體。故曰孚於嘉。</p><h3 id="象曰。孚於嘉。位正中也。" tabindex="-1">象曰。孚於嘉。位正中也。 <a class="header-anchor" href="#象曰。孚於嘉。位正中也。" aria-label="Permalink to “象曰。孚於嘉。位正中也。”">​</a></h3><p>二五皆當位。故曰正中。</p><p>上六。拘繫之。乃從維之。王用亨於西山。</p><p>伏艮為拘為山。兌西故曰西山，兌口故曰亨。王渭五。三至上正反巽。巽為繩。故曰系。曰維。虞翻曰。兩系稱維。正反兩類詩所謂縶之維之也。卦以隨為義。六窮於上。五恐其去。拘繫之。從維之。或即其隱居之處而宴享之。言六無所隨。而五必隨之也。西溪易說雲。先儒說易。遇西山西鄰。皆曰文王事也。可謂大謬。</p><h3 id="象曰。拘繫之。上窮也。" tabindex="-1">象曰。拘繫之。上窮也。 <a class="header-anchor" href="#象曰。拘繫之。上窮也。" aria-label="Permalink to “象曰。拘繫之。上窮也。”">​</a></h3><p>窮盡也。</p>',29)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
